class Solution {
    public:vector<int> maximumBobPoints(int numArrows,vector<int>& aliceArrows){
        int best=-1;
        vector<int> answer(12);
        for(int mask=0;mask<(1<<12);++mask){
            int required=0,score=0;
            for(int i=0;i<12;++i)if(mask>>i&1){
                required+=aliceArrows[i]+1;
                score+=i;
            }
            if(required<=numArrows&&score>best){
                best=score;
                fill(answer.begin(),answer.end(),0);
                for(int i=0;i<12;++i)if(mask>>i&1)answer[i]=aliceArrows[i]+1;
                answer[0]+=numArrows-required;
            }
        }
        return answer;
    }
};
